<script>
  import AppIcon from './AppIcon.svelte';
  import {tick,onDestroy,createEventDispatcher} from 'svelte';
  import CleanupRetries from './CleanupRetries.svelte';
  import {copyTranscriptText} from '../entryPresentation.js';
  let copyFeedback='';
  async function copyReport(){const result=await copyTranscriptText(JSON.stringify(health,null,2),navigator.clipboard);copyFeedback=result.error||'Diagnostic report copied.';}
  import TrashPanel from './TrashPanel.svelte';
  import MayDoBackfill from './MayDoBackfill.svelte';
  import TagMaintenance from './TagMaintenance.svelte';
  import TranscriptionBatch from './TranscriptionBatch.svelte';
  export let open=false, connected=false, noteFilter='all', section='General';
  const dispatch=createEventDispatcher();
  const sections=['General','Folders','Transcription','Cleanup and MayDos','Search','Data and maintenance','Integrations','About'];
  const sectionIcons={General:'settings',Folders:'folder',Transcription:'waveform','Cleanup and MayDos':'maydos',Search:'search','Data and maintenance':'library',Integrations:'link',About:'info'};
  let content, maintenanceOpen = {};
  let defaultModel = 'bark-pro', modelSaved = '';
  function chooseSection(name){section=name;error='';message='';if(content)content.scrollTop=0;}
  let dialog,priorFocus,settings=null,health=null,stats=null,probe=null,error='',message='',busy=false,timer,markSelected={},markConfirm=false;
  async function fetchJson(url,body){const response=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
  async function refresh(){error='';try{[settings,stats,probe]=await Promise.all([fetchJson('/settings'),fetchJson('/notes/stats'),fetchJson('/tools/probe')]);defaultModel=settings.transcription.model;}catch(e){error=e.message;}}
  async function saveModel(){busy=true;error='';modelSaved='';try{settings=await fetchJson('/settings/transcription',{model:defaultModel});defaultModel=settings.transcription.model;health=null;modelSaved='Saved. The next transcription will use this model.';}catch(e){error=e.message;}finally{busy=false;}}
  async function action(url,body){busy=true;error='';message='';try{const data=await fetchJson(url,body);message={summary:({'/tools/index/rebuild':'Words index rebuilt.','/tools/entries/identity':'Entry identity check finished.','/tools/probe':'Audio scan started.','/tools/probe/mark':'Reviewed audio failures updated.'})[url]||'Action completed.',details:JSON.stringify(data,null,2)};await refresh();}catch(e){error=e.message;}finally{busy=false;}}
  async function checks(){busy=true;error='';try{const response=await fetch('/health?fresh=1');const data=await response.json();if(!Array.isArray(data.checks))throw new Error(data.error||'Could not run diagnostics.');health=data;}catch(e){error=e.message;}finally{busy=false;}}
  async function scan(){markConfirm=false;markSelected={};await action('/tools/probe',{apply:false});timer=setInterval(async()=>{if(!open){clearInterval(timer);return;}try{probe=await fetchJson('/tools/probe');if(!probe.running)clearInterval(timer);}catch(e){error=e.message;clearInterval(timer);}},1500);}
  $: if(dialog&&open&&!dialog.open){priorFocus=document.activeElement;dialog.showModal();void refresh();tick().then(()=>dialog.querySelector('button')?.focus());}
  $: if(dialog&&!open&&dialog.open){dialog.close();clearInterval(timer);(priorFocus?.isConnected && priorFocus.getClientRects().length ? priorFocus : document.querySelector('[data-settings-trigger]')?.getClientRects().length ? document.querySelector('[data-settings-trigger]') : document.querySelector('[data-settings-trigger]'))?.focus({preventScroll:true});}
  onDestroy(()=>clearInterval(timer));
</script>
<dialog bind:this={dialog} aria-label="Settings" on:cancel|preventDefault={()=>open=false}>
  <header><h2 class="dw-with-icon"><AppIcon name="settings"/>Settings</h2><button class="dw-btn-secondary" on:click={()=>open=false}><AppIcon name="close" size={16}/>Close Settings</button></header>
  {#if open}
  <label class="section-picker">Section<select class="dw-input" aria-label="Settings section" value={section} on:change={event=>chooseSection(event.currentTarget.value)}>{#each sections as name}<option>{name}</option>{/each}</select></label>
  <div class="settings-layout"><nav aria-label="Settings sections">{#each sections as name}<button class="dw-btn-secondary" aria-current={section===name?'page':undefined} on:click={()=>chooseSection(name)}><AppIcon name={sectionIcons[name]} size={16}/>{name}</button>{/each}</nav><section class="settings-content" aria-label={section} bind:this={content}>
  {#if error}<p class="dw-error" role="alert">{error}</p><button class="dw-btn-secondary" on:click={refresh}>Retry loading Settings</button>{/if}
  {#if !settings}<p>Loading effective settings…</p>{:else}
    <h3 class="dw-with-icon"><AppIcon name={sectionIcons[section]}/>{section}</h3>{#if !['General','Transcription','Data and maintenance'].includes(section)}<p class="configuration-note dw-muted">Current configuration · edit the config file and restart to change settings. See Advanced below.</p>{/if}
    {#if section==='General'}<p>The library adapts to the window. Opening an entry keeps a compact list beside its reader. On a small screen, Back to entries returns to your list position.</p><p>Playback speed and Follow are reader controls. Filters and reader position are retained for this browser session. Reduced motion follows your system setting.</p><button class="dw-btn-secondary" on:click={()=>{open=false;dispatch('help');}}>Keyboard shortcuts and reading help</button>
    {:else if section==='Folders'}<p>Audio remains in your configured folders. Watch imports wait for writes to settle.</p>{#each settings.folders.roots as root}<p><code>{root.file}</code> {root.exists?'Available':'Missing · create the folder or correct watch.roots in config'}</p>{/each}<dl><dt>Browser import destination</dt><dd>{settings.folders.browserDropFolder}</dd><dt>Watch settle time</dt><dd>{settings.folders.settleMinutes} minutes</dd><dt>Browser settle time</dt><dd>{settings.folders.browserSettleMs} ms</dd><dt>Watch year folders</dt><dd>{settings.folders.recursiveYears?'Yes':'No'}</dd></dl>
    {:else if section==='Transcription'}
      <p>Transcription runs locally. New recordings are assessed and prepared automatically, preserving their timing.</p>
      <label class="model-setting">Default transcription model<select class="dw-input" bind:value={defaultModel} disabled={busy||!connected||settings.transcription.modelLocked} on:change={()=>modelSaved=''}><option value="bark-pro">Bark Pro · English</option><option value="large-v3">Whisper large-v3 · multilingual</option><option value="turbo">Whisper turbo · faster</option></select></label>
      <p class="dw-muted">Used for new recordings, imports and retries. New improvement attempts and batch previews start with this choice. Running jobs and saved batch selections keep their model.</p>
      {#if settings.transcription.modelLocked}<p role="status">Controlled by DICTA_TRANSCRIPTION_MODEL. Remove that environment override to save a choice here.</p>{/if}
      <button class="dw-btn-primary" disabled={busy||!connected||settings.transcription.modelLocked||defaultModel===settings.transcription.model} on:click={saveModel}><AppIcon name="check" size={16}/>{busy?'Saving…':'Save default model'}</button>
      {#if modelSaved}<p class="dw-status dw-tone-success" role="status">{modelSaved}</p>{/if}
      <p class="dw-muted">Saved to your configuration immediately; no restart needed. Existing entries stay as they are.</p>
      {#if defaultModel==='bark-pro'}<p>Bark Pro includes quiet speech and silence, with estimated passage timing for playback. Review important wording against the audio.</p>{#if !settings.transcription.bark.available}<p class="dw-error" role="status">{settings.transcription.bark.reason} You can also choose Whisper above.</p>{/if}{/if}
      <button class="dw-btn-secondary" disabled={busy||!connected} on:click={checks}>Check saved model setup</button>
      <details class="dw-disclosure"><summary>Runtime and processing details</summary><dl><dt>Bark Python</dt><dd>{settings.transcription.bark.python}</dd><dt>Bark device</dt><dd>{settings.transcription.bark.device}</dd><dt>Whisper Python</dt><dd>{settings.transcription.whisper.python}</dd><dt>Whisper device / compute type</dt><dd>{settings.transcription.whisper.device} / {settings.transcription.whisper.computeType}</dd><dt>Whisper worker</dt><dd>{settings.transcription.worker} · starts when needed</dd><dt>Queue</dt><dd>{settings.transcription.queue.active?'Enabled':'Disabled'} · concurrency {settings.transcription.queue.concurrency}</dd><dt>Preprocessing</dt><dd>{settings.transcription.preprocess?'Automatic · requires ffmpeg':'Unfiltered audio'}</dd><dt>Whisper vocabulary hints</dt><dd>{settings.transcription.promptTerms.join(', ')||'None'}</dd></dl><p>Change these runtime options in the configuration file, then restart. Saved audio can wait in Activity if processing is unavailable.</p></details>
      <button class="dw-btn-secondary" on:click={()=>chooseSection('Data and maintenance')}><AppIcon name="refresh" size={16}/>Retranscribe older recordings…</button>
    {:else if section==='Cleanup and MayDos'}<p>Cleanup and action extraction send transcript text and tags to the configured model host. Saved transcripts and MayDos remain usable when this optional service is unavailable.</p><dl><dt>Configured host</dt><dd>{settings.cleanup.machine||'Not configured'}</dd><dt>Model</dt><dd>{settings.cleanup.cleanModel||'Not configured'}</dd><dt>MayDo extraction</dt><dd>{settings.cleanup.available?'Available':settings.cleanup.disabledReason}</dd><dt>Cleanup queue</dt><dd>{settings.cleanup.queue.active?'Enabled':'Disabled'}</dd><dt>Required for startup checks</dt><dd>{settings.cleanup.required?'Yes':'No · optional'}</dd><dt>Save model chats</dt><dd>{settings.cleanup.saveChats?'Enabled':'Disabled'}</dd></dl><p>New cleanup extracts possible actions as Suggested. Existing selections and statuses are preserved. Bulk extraction is under Data and maintenance.</p><button class="dw-btn-secondary" disabled={busy||!connected} on:click={checks}>Test configured services</button>
    {:else if section==='Search'}<dl><dt>Configured mode</dt><dd>{settings.search.search}</dd><dt>Embedding host selection</dt><dd>{settings.search.embedHost}</dd><dt>Embedding model preference</dt><dd>{settings.search.embedModel||'Automatic selection'}</dd><dt>Index</dt><dd>{settings.search.index}</dd><dt>Coverage</dt><dd>{stats?.notes||0} entries · {stats?.embedded||0} embedded</dd></dl><p>Words search works without embeddings. Meaning search sends transcript text and query text to the selected embedding host when enabled. The index is a derived cache; rebuilding never retranscribes audio.</p><button class="dw-btn-secondary" disabled={busy||!connected||stats?.indexing} on:click={()=>action('/tools/index/rebuild',{})}>{stats?.indexing?'Rebuilding…':'Rebuild words index'}</button>
    {:else if section==='Data and maintenance'}
      <button class="dw-btn-secondary" on:click={()=>{open=false;dispatch('activity');}}>Open Activity · processing and retries</button>
      <details class="dw-disclosure" bind:open={maintenanceOpen.trash}><summary><AppIcon name="trash" size={16}/>Trash and recovery</summary>{#if maintenanceOpen.trash}<TrashPanel {connected}/>{/if}</details>
      <details class="dw-disclosure" bind:open={maintenanceOpen.maydos}><summary><AppIcon name="maydos" size={16}/>Extract MayDos from older entries</summary>{#if maintenanceOpen.maydos}<MayDoBackfill {connected} on:change={event=>dispatch('job',event.detail)}/>{/if}</details>
      <details class="dw-disclosure" bind:open={maintenanceOpen.transcription}><summary><AppIcon name="waveform" size={16}/>Retranscribe older entries</summary>{#if maintenanceOpen.transcription}<TranscriptionBatch {connected}/>{/if}</details>
      <details class="dw-disclosure" bind:open={maintenanceOpen.cleanup}><summary><AppIcon name="refresh" size={16}/>Retry failed cleanup</summary>{#if maintenanceOpen.cleanup}<CleanupRetries {connected} on:activity={()=>{open=false;dispatch('activity');}}/>{/if}</details>
      <details class="dw-disclosure" bind:open={maintenanceOpen.tags}><summary><AppIcon name="tags" size={16}/>Consolidate tags</summary>{#if maintenanceOpen.tags}<TagMaintenance {connected}/>{/if}</details>
      <details class="dw-disclosure"><summary><AppIcon name="activity" size={16}/>Check pending audio</summary><p>Checks pending files in watched folders. Marking reviewed failures adds unreadable metadata; audio is retained.</p><button class="dw-btn-secondary" disabled={busy||!connected||probe?.running} on:click={scan}>{probe?.running?'Scanning…':'Scan pending audio'}</button>{#if probe?.finishedAt}<p>{probe.bad} failures in {probe.pending} pending files</p>{#each probe.files||[] as hit}<label><input type="checkbox" bind:checked={markSelected[hit.file]} disabled={busy}/><span>{hit.reason}<code>{hit.file}</code></span></label>{/each}{#if probe.files?.length}<label><input type="checkbox" bind:checked={markConfirm}/> Mark selected files unreadable; retain audio</label><button class="dw-btn-secondary" disabled={busy||!connected||!markConfirm||!Object.values(markSelected).some(Boolean)} on:click={()=>action('/tools/probe/mark',{files:Object.keys(markSelected).filter(file=>markSelected[file])})}>Mark reviewed failures</button>{/if}{/if}<button class="dw-text-btn" on:click={()=>{noteFilter='unreadable';open=false;}}>Show unreadable entries</button></details>
      <details class="dw-disclosure"><summary><AppIcon name="link" size={16}/>Stable entry identities</summary><p>Add IDs to legacy sidecars in the index, including Holding and Unfiled. IDs survive moves and restores. This updates sidecars; active processing is skipped with a retryable report.</p><button class="dw-btn-secondary" disabled={busy||!connected} on:click={()=>action('/tools/entries/identity',{})}>Backfill entry IDs</button></details>
    {:else if section==='Integrations'}<p>MCP runs locally over stdio. Clients share these configured roots and derived index.</p><pre>{JSON.stringify(settings.integrations.mcp,null,2)}</pre><p>ExoMetaCortex: {settings.integrations.exoMetaCortex}</p>
    {:else}<p>DictaWhisper {settings.version}</p><dl><dt>API endpoint</dt><dd>{settings.network.apiUrl}</dd><dt>Browser origin</dt><dd>{typeof location!=='undefined'?location.origin:''}</dd><dt>Configured exposure</dt><dd>{settings.network.listenHost} · Tailscale {settings.network.tailscale?'enabled':'disabled'}</dd><dt>Allowed browser origins</dt><dd>{settings.network.corsOrigins.join(', ')}</dd></dl><button class="dw-btn-secondary" disabled={busy||!connected} on:click={checks}>{busy?'Checking…':'Run diagnostics'}</button><button class="dw-btn-secondary" on:click={()=>{open=false;dispatch('help');}}>Open task help</button><a href="https://dictawhisper.com" target="_blank" rel="noreferrer">Product documentation</a>{/if}
    {#if health}<details class="dw-disclosure" open><summary><AppIcon name="activity" size={16}/>Diagnostic results · {health.ok?(health.degraded?'Ready with warnings':'Ready'):'Needs attention'}</summary>{#each ['transcription','cleanup','search','runtime'] as group}<h4>{group==='cleanup'?'Optional cleanup':group==='search'?'Search readiness':group==='transcription'?'Required for transcription':'Runtime and folders'}</h4>{#each health.checks?.filter(check=>(check.group||'runtime')===group)||[] as check}<p>{check.level}: {check.message}</p>{/each}{/each}<button class="dw-btn-secondary" on:click={copyReport}>Copy diagnostic report</button><p role="status">{copyFeedback}</p><details class="dw-disclosure"><summary>Plain diagnostic report</summary><pre>{JSON.stringify(health,null,2)}</pre></details></details>{/if}
    <details class="dw-disclosure"><summary><AppIcon name="settings" size={16}/>Advanced · loaded configuration</summary><p>The default model can be saved under Transcription. For other options, edit this configuration file and restart DictaWhisper.</p><code>{settings.configPath}</code><p>Set the DICTA_CONFIG environment variable to this file to select it explicitly.</p><p>Checkout: <code>pnpm doctor</code></p><p>Installed CLI: <code>dictawhisper doctor</code></p><p>These commands can test runtimes and model connections. Keep paths and journal details private when sharing diagnostics.</p></details>
  {/if}
  {#if message}<p class="dw-status dw-tone-success" role="status"><AppIcon name="check" size={16}/>{message.summary}</p><details class="dw-disclosure"><summary>Action details</summary><pre>{message.details}</pre></details>{/if}
  </section></div>
  {/if}
</dialog>
<style>
  dialog{position:fixed;inset:0 0 0 auto;margin:0;width:min(840px,100vw);max-width:100vw;height:100dvh;max-height:100dvh;padding:0;background:var(--dw-surface);color:var(--dw-text);border:0;border-left:1px solid var(--dw-border);overflow:hidden;}
  dialog[open]{display:flex;flex-direction:column;}dialog::backdrop{background:#0009;}
  header{flex-shrink:0;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 20px;border-bottom:1px solid var(--dw-border);}
  .settings-layout{display:grid;grid-template-columns:190px minmax(0,1fr);min-height:0;flex:1;}
  nav{display:flex;flex-direction:column;gap:4px;padding:16px 12px;border-right:1px solid var(--dw-border);overflow:auto;}
  nav button{width:100%;text-align:left;justify-content:flex-start;border-color:transparent;background:transparent;margin:0;min-height:44px;line-height:1.4;}
  nav button[aria-current],nav button[aria-current]:hover{color:var(--dw-accent-bright);background:rgb(231 182 87 / .12);border-color:#796442;}
  .settings-content{padding:20px;overflow:auto;min-width:0;scrollbar-gutter:stable;}
  .section-picker{display:none;}h2{font-size:20px;}h3{display:flex;justify-content:flex-start;font-size:18px;margin:0 0 12px;}h4{font-size:14px;margin:14px 0 6px;}
  button,summary{min-height:44px;}details{border-top:1px solid var(--dw-border);margin-top:16px;padding:6px 0;}summary{font-weight:600;}
  p{line-height:1.6;margin:10px 0;}label{display:flex;gap:10px;align-items:flex-start;margin:12px 0;line-height:1.5;}
  dt{font-size:12px;color:var(--dw-text-muted);margin-top:12px;}dd{margin:4px 0;overflow-wrap:anywhere;}
  code,pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;}button{margin:4px 6px 4px 0;}input{flex-shrink:0;}
  .configuration-note{padding:10px 12px;border-left:2px solid var(--dw-info);background:var(--dw-info-bg);margin-bottom:16px;}
  .model-setting{flex-direction:column;gap:6px;font-weight:600;}.model-setting select{width:100%;min-width:0;min-height:44px;}
  @media(max-width:600px){header{padding:12px 16px;}nav{display:none;}.settings-layout{display:flex;}.settings-content{padding:16px;flex:1;}.section-picker{display:flex;align-items:center;padding:12px 16px;margin:0;border-bottom:1px solid var(--dw-border);font-size:13px;}.section-picker select{flex:1;min-width:0;min-height:44px;}header button{margin:0;}}
</style>
